import sys
input = sys.stdin.read

data = input().split()
n, m, min_temp, max_temp = map(int, data[:4])
temperatures = list(map(int, data[4:]))

def is_correct(n, m, min_temp, max_temp, temperatures):
    has_min = min_temp in temperatures
    has_max = max_temp in temperatures

    if n - m == 2 and has_min and has_max and len(set(temperatures)) == 1:
        return False

    missing_temperatures = n - m

    if has_min and has_max:
        return missing_temperatures >= 0

    if not has_min:
        missing_temperatures -= 1
    if not has_max:
        missing_temperatures -= 1

    return missing_temperatures >= 0

if is_correct(n, m, min_temp, max_temp, temperatures):
    print("Correct")
else:
    print("Incorrect")

